/* #53: read existing progress only. No new keys, no automatic mastery or audio. */
(()=>{'use strict';const t=document.getElementById('learning-route-data');if(!t)return;let rows;try{rows=JSON.parse(t.content.textContent);}catch{return;}if(!Array.isArray(rows)||rows.some(x=>!x||!/^[a-z0-9-]+$/.test(x.id)||x.href!==`artikler/${x.id}.html`))return;
const en=document.documentElement.lang==='en';const text=(a,b)=>en?b:a;
async function update(){const account=window.ModusAccount;if(account)try{await account.ready;}catch{}let storage;try{storage=localStorage;}catch{}
const passed=id=>{try{return account?account.has(id):storage?.getItem('modus.article-quiz.v1.'+id)==='passed';}catch{return false;}};let opened={};try{opened=JSON.parse(storage?.getItem('modus.atlas.article-evidence.v1')||'{}')||{};}catch{}
const next=rows.find(x=>!passed(x.id))||rows[0],count=rows.filter(x=>passed(x.id)).length;
document.querySelectorAll('[data-route-resume]').forEach(e=>{e.querySelector('[data-route-continue]').href=next.href;e.querySelector('[data-route-continue]').textContent=count===rows.length?text('Repeter fra starten','Review from the beginning'):count?text('Fortsett der du slapp','Continue where you left off'):text('Begynn fra starten','Start from the beginning');e.querySelector('[data-route-status]').textContent=next.title+' · '+text(`${count} av ${rows.length} quizer fullført. Fortsettelse viser første artikkel uten fullført quiz, ikke eksakt leseposisjon.`,`${count} of ${rows.length} quizzes completed. Continue selects the first article without a completed quiz, not an exact reading position.`);});
document.querySelectorAll('[data-route-step]').forEach(e=>{const id=e.dataset.routeStep;e.querySelector('[data-route-step-status]').textContent=(opened[id]?.opened===true?text('Åpnet · ','Opened · '):'')+(passed(id)?text('Quiz fullført','Quiz completed'):text('Quiz ikke fullført','Quiz not completed'));});}
let ref='';try{const u=new URL(document.referrer);if(u.origin===location.origin)ref=u.pathname.match(/\/artikler\/([a-z0-9-]+)(?:\.html)?$/)?.[1]||'';}catch{}
const id=new URLSearchParams(location.search).get('fromArticle')||ref,row=rows.find(x=>x.id===id),back=document.querySelector('[data-route-return]');if(row&&back){const a=back.querySelector('[data-route-return-link]');a.href=row.href;a.textContent=text('Tilbake: ','Back: ')+row.title;back.hidden=false;}
for(const e of ['pageshow','storage'])window.addEventListener(e,update);document.addEventListener('modus-account-change',update);update();})();
